def copy_report_dates_to_records(apps, schema_editor):
    """ရှိပြီးသား report_90day_update_1/2/3 ရက်စွဲများကို record အဖြစ် ရွှေ့ပြီး
    report_90day_date (နောက်တစ်ကြိမ် report ရက်) ကို အသစ်ဆုံးရက်စွဲ + 90 ရက် ပြန်တွက်သည်."""
    EmployeeModel = apps.get_model("core", "EmployeeModel")
    ReportModel = apps.get_model("core", "Employee90DayReportModel")

    records = []
    for employee in EmployeeModel.objects.all().iterator():
        dates = {
            employee.report_90day_update_1,
            employee.report_90day_update_2,
            employee.report_90day_update_3,
        }
        dates.discard(None)
        if not dates:
            continue
        for report_date in sorted(dates):
            records.append(ReportModel(employee=employee, report_date=report_date))
        employee.report_90day_date = max(dates) + timedelta(days=90)
        employee.save(update_fields=["report_90day_date"])

    ReportModel.objects.bulk_create(records)


